 p.locator('[name=cleanup-data-confirm]').check();p.locator('#uninstall-name').fill(name);p.locator('#outcome').select_option(outcome);submit(p);oid=ev(p,'S.operations[0].id');click(p,'finishdemo',where='#modal');close(p);return oid
